import{_ as n,o,c as d,j as e,a as t,aa as i}from"./chunks/framework.BAs_AphD.js";const r="/buildary-help-preview/academy/img/zalozeni-deniku/12.webp",l="/buildary-help-preview/academy/img/zalozeni-deniku/03.webp",s="/buildary-help-preview/media/cs/diary/provazane_deniky.png",m=JSON.parse('{"title":"Založit deník","description":"","frontmatter":{"title":"Založit deník","wiki":"cs:diary:diarysetup"},"headers":[],"relativePath":"diary/diarysetup.md","filePath":"diary/diarysetup.md","lastUpdated":1794209661000}'),k={name:"diary/diarysetup.md"};function p(u,a,v,y,h,b){return o(),d("div",null,[...a[0]||(a[0]=[e("h1",{id:"zalozit-denik",tabindex:"-1"},[t("Založit deník "),e("a",{class:"header-anchor",href:"#zalozit-denik","aria-label":'Permalink to "Založit deník"'},"​")],-1),e("p",null,"Deník zakládáte v Seznamu deníků stavby. Vyberete typ deníku, firmu, která ho vede, doklad, na jehož základě se stavba realizuje, a datum zavedení. Na jedné stavbě můžete vést libovolný počet deníků.",-1),e("p",null,[t("Krok za krokem: "),e("a",{href:"/buildary-help-preview/akademie/zalozeni-deniku"},"Založit stavební deník"),t(" v Akademii.")],-1),e("div",{class:"video"},[e("iframe",{src:"https://www.youtube-nocookie.com/embed/zKdiW74IGV8",title:"Video: Založení a nastavení deníku",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),i('<h2 id="kolik-deniku-vest" tabindex="-1">Kolik deníků vést <a class="header-anchor" href="#kolik-deniku-vest" aria-label="Permalink to &quot;Kolik deníků vést&quot;">​</a></h2><p>Na menší stavbě obvykle stačí jeden stavební deník. Na velkých stavbách se často vede:</p><ul><li>samostatný deník pro každý stavební objekt (deník části stavby),</li><li><strong>centrální deník</strong> pro společné údaje celé stavby,</li><li>vlastní deníky významných podzhotovitelů,</li><li>samostatné deníky pro speciální práce, které to svou povahou vyžadují.</li></ul><p>Pokud máte osvědčený způsob, jak deníky na stavbě členit, držte se ho – Buildary ho podpoří.</p><p>Deník může založit uživatel s potřebnými právy na doméně nebo stavbě, viz <a href="/buildary-help-preview/diary/userpermissions">Kdo co smí v deníku</a>. Kdo deník založí, stává se jeho vlastníkem a automaticky se zapíše mezi oprávněné osoby jako administrátor.</p><h2 id="novy-denik-nebo-kopie" tabindex="-1">Nový deník nebo kopie <a class="header-anchor" href="#novy-denik-nebo-kopie" aria-label="Permalink to &quot;Nový deník nebo kopie&quot;">​</a></h2><p>V <strong>Seznamu deníků</strong> jsou dvě tlačítka:</p><table tabindex="0"><thead><tr><th>Tlačítko</th><th>Kdy ho použít</th></tr></thead><tbody><tr><td><strong>Nový deník</strong></td><td>Zakládáte deník od začátku.</td></tr><tr><td><strong>Nový deník kopií</strong></td><td>Chcete převzít nastavení existujícího deníku stavby. Kromě nastavení můžete zkopírovat i oprávněné osoby.</td></tr></tbody></table><h2 id="udaje-deniku" tabindex="-1">Údaje deníku <a class="header-anchor" href="#udaje-deniku" aria-label="Permalink to &quot;Údaje deníku&quot;">​</a></h2><figure class="shot" style="--w:760px;"><img src="'+r+'" alt="Vyplněný formulář Nový deník" loading="lazy"></figure><table tabindex="0"><thead><tr><th>Pole</th><th>Co vyplnit</th></tr></thead><tbody><tr><td><strong>Typ deníku</strong></td><td>Druh deníku, viz <a href="#typy-deniku">Typy deníků</a>. Podle typu se deníky řadí v Seznamu deníků.</td></tr><tr><td><strong>Deník vede</strong></td><td>Firma, která deník vede. Vybíráte z firem v <a href="/buildary-help-preview/diary/projectteam">projektovém týmu</a>.</td></tr><tr><td><strong>Nadřazený deník</strong></td><td>Nepovinné. Viz <a href="#nadrazeny-denik">Nadřazený deník</a>.</td></tr><tr><td><strong>Druh dokladu</strong></td><td>Doklad, na jehož základě se stavba realizuje – například Ohlášení, Stavební povolení, Veřejnoprávní smlouva, Územní souhlas, Povolení záměru nebo Povolení (NStZ).</td></tr><tr><td><strong>Číslo jednací</strong>, <strong>Vydal</strong></td><td>Číslo jednací dokladu a úřad, který ho vydal.</td></tr><tr><td><strong>Datum vydání</strong>, <strong>Datum nabytí právní moci</strong></td><td>Data dokladu.</td></tr><tr><td><strong>Datum zavedení deníku</strong></td><td>Počáteční datum deníku, zpravidla den předání staveniště. Může být v minulosti i v budoucnosti.</td></tr><tr><td><strong>Datum ukončení deníku</strong></td><td>Nepovinné. Po tomto datu už do deníku nejde vkládat denní záznamy.</td></tr></tbody></table><p>Všechny údaje můžete později změnit na záložce <strong>Úvodní list deníku</strong> v <a href="/buildary-help-preview/diary/diaryidentification#uvodni-list-deniku">identifikačních údajích deníku</a>.</p><h2 id="typy-deniku" tabindex="-1">Typy deníků <a class="header-anchor" href="#typy-deniku" aria-label="Permalink to &quot;Typy deníků&quot;">​</a></h2><figure class="shot" style="--w:640px;"><img src="'+l+'" alt="Rozbalený seznam typů deníků" loading="lazy"></figure><p>V poli <strong>Typ deníku</strong> si vyberete z těchto typů:</p><ul><li>Stavební deník</li><li>Stavební deník /stavby - centrální/</li><li>Stavební deník /část stavby/ (objektový deník)</li><li>Zjednodušený záznam o stavbě</li><li>Deník podzhotovitele</li><li>Deník speciálních prací</li><li>Deník koordinátora BOZP</li><li>Kniha BOZP</li><li>Stavební deník (údržba a opravy staveb státních drah)</li><li>Požární kniha</li></ul><h3 id="udaje-o-casti-stavby" tabindex="-1">Údaje o části stavby <a class="header-anchor" href="#udaje-o-casti-stavby" aria-label="Permalink to &quot;Údaje o části stavby&quot;">​</a></h3><p>U typů <strong>Stavební deník /část stavby/</strong>, <strong>Deník podzhotovitele</strong> a <strong>Deník speciálních prací</strong> vyplníte navíc:</p><ul><li><strong>Název části stavby</strong> – celý název objektu nebo části stavby,</li><li><strong>Zkrácený název části stavby</strong>,</li><li><strong>Číslo části stavby</strong> – zobrazuje se i ve sloupci Číslo části stavby v Seznamu deníků.</li></ul><figure class="shot" style="--w:640px;"><img src="'+s+'" alt="Deník podzhotovitele s vyplněnou částí stavby a nadřazeným deníkem" loading="lazy"></figure><h3 id="nadrazeny-denik" tabindex="-1">Nadřazený deník <a class="header-anchor" href="#nadrazeny-denik" aria-label="Permalink to &quot;Nadřazený deník&quot;">​</a></h3><p>V poli <strong>Nadřazený deník</strong> deník podřídíte jinému deníku stavby – typicky deník podzhotovitele nebo části stavby hlavnímu či centrálnímu deníku. Do nadřazeného deníku pak můžete kopírovat záznamy z deníků, které jsou mu podřízené, viz <a href="/buildary-help-preview/diary/copydailyentries">Kopírovat záznamy</a>.</p><h2 id="po-zalozeni" tabindex="-1">Po založení <a class="header-anchor" href="#po-zalozeni" aria-label="Permalink to &quot;Po založení&quot;">​</a></h2><p>Po uložení se aplikace zeptá <strong>Chcete pokračovat nastavením deníku?</strong> Klikněte na <strong>Ano</strong> a pokračujte rovnou tím, co je potřeba udělat před prvním zápisem:</p><ul><li>obsah a pravidla deníku – <a href="/buildary-help-preview/diary/diarysettings">Nastavit deník</a>,</li><li>další oprávněné osoby a loga – <a href="/buildary-help-preview/diary/diaryidentification#opravnene-osoby">Identifikační údaje deníku</a>.</li></ul><p>Tlačítkem <strong>Později</strong> nastavení odložíte. Najdete ho kdykoli v <strong>Identifikačních údajích</strong> deníku.</p>',26)])])}const z=n(k,[["render",p]]);export{m as __pageData,z as default};
